mapper.select:
SELECT h.ID, h.CATEGORY_ID, h.TITLE, h.CONTENT, h.SORT_NUM, h.STATUS, h.CREATE_TIME, h.UPDATE_TIME, c.NAME AS CATEGORY_NAME, c.ICON AS CATEGORY_ICON FROM HELP h LEFT JOIN HELP_CATEGORY c ON h.CATEGORY_ID = c.ID WHERE h.STATUS = '1'
AND h.CATEGORY_ID = #{categoryId}
ORDER BY h.SORT_NUM ASC

mapper.update:
UPDATE HELP
CATEGORY_ID = #{categoryId}, TITLE = #{title}, CONTENT = #{content}, SORT_NUM = #{sortNum}, STATUS = #{status}
WHERE ID = #{id}
